// ═══════════════════════════════════════════════════════════════════
// 电影大师 · 图片归位 + 补 imgthink + 补图片（合并版 v3.0）
//  · 一个上拉选项：图片归位 / 修复 imgthink / 修复图片数量
//  · 生成后只做本地检测（不调模型），有任何一项需要处理就显示「需修复」
//  · 图片归位：连在一起的图、以及落在正文标签外面的图，都按正文段落归位
//  · 补 imgthink：缺 <imgthink> 的 <image> 由 AI 补 think + 重写提示词
//  · 补图片：正文标签内挑段落，AI 出图，凑够 3 张
// ═══════════════════════════════════════════════════════════════════

const CFG = {
  auto: false,          // true=生成后自动跑「图片归位」（默认只检测）
  dryRun: false,
  maxRepair: 4,
  maxAdd: 3,
  minImages: 3,
  minParaChars: 15,
  maxParagraphs: 60,
  historyChars: 1200,
  minScore: 0.08
};

const STORE_KEY = 'fm_move_body_tag';
let bodyTag = '';
try { bodyTag = (typeof localStorage !== 'undefined' && localStorage.getItem(STORE_KEY)) || ''; } catch (e) {}

const TH = (typeof TavernHelper !== 'undefined' && TavernHelper) || globalThis;
const getMsgs = TH.getChatMessages || globalThis.getChatMessages;
const setMsgs = TH.setChatMessages || globalThis.setChatMessages;
const onEvent = TH.eventOn || globalThis.eventOn;
const EVENTS  = TH.tavern_events || globalThis.tavern_events || {};
const genRaw  = TH.generateRaw || globalThis.generateRaw;
const gen     = TH.generate || globalThis.generate;
const toast   = TH.toastr || globalThis.toastr;

const log = (...a) => console.log('[FM-fix]', ...a);
const seen = new Set();

const UNIT_RE = /<imgthink>[\s\S]*?<\/imgthink>\s*<image[^>]*>[\s\S]*?<\/image>|<image[^>]*>[\s\S]*?<\/image>/g;

// ── DOM 小工具 ───────────────────────────────────────────────────
function docRef() {
  try { if (typeof window !== 'undefined' && window.parent && window.parent.document) return window.parent.document; } catch (e) {}
  try { if (typeof document !== 'undefined') return document; } catch (e) {}
  return null;
}

function findButton(doc) {
  if (!doc || !doc.querySelectorAll) return null;
  const list = doc.querySelectorAll('button, .menu_button, [role="button"]');
  for (const b of list) {
    const t = (b.textContent || '').trim();
    if (t === '图文修复' || t === '修复本条' || t === '需修复') return b;
  }
  return null;
}

function styleLike(el, btn) {
  try {
    const cs = (typeof getComputedStyle === 'function') ? getComputedStyle(btn) : null;
    if (!cs) return;
    el.style.background = cs.backgroundColor;
    el.style.color = cs.color || '#fff';
    el.style.border = cs.border || 'none';
    el.style.borderRadius = cs.borderRadius;
    el.style.fontSize = cs.fontSize;
    el.style.fontFamily = cs.fontFamily;
    el.style.height = cs.height;
    el.style.padding = '0 8px';
    el.style.cursor = 'pointer';
  } catch (e) {}
}

// ── 文本工具 ─────────────────────────────────────────────────────
function grams(s) {
  const t = String(s || '').replace(/[^\u4e00-\u9fa5A-Za-z0-9]/g, '');
  const m = new Map();
  for (const ch of t) m.set(ch, (m.get(ch) || 0) + 0.35);
  for (let i = 0; i + 1 < t.length; i++) { const b = t.slice(i, i + 2); m.set(b, (m.get(b) || 0) + 1); }
  return m;
}

function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (const w of a.values()) na += w * w;
  for (const w of b.values()) nb += w * w;
  for (const [k, w] of a) { const v = b.get(k); if (v) dot += w * v; }
  return dot / Math.sqrt(Math.max(na * nb, 1e-6));
}

function scan(text) {
  const units = [];
  UNIT_RE.lastIndex = 0;
  let m;
  while ((m = UNIT_RE.exec(text)) !== null) units.push({ start: m.index, end: m.index + m[0].length, raw: m[0] });
  return units;
}

function countImages(text) { return (text.match(/<image[^>]*>/g) || []).length; }

function findOrphans(msg) {
  const out = [];
  const re = /<image[^>]*>[\s\S]*?<\/image>/g;
  let m;
  while ((m = re.exec(msg)) !== null) {
    const before = msg.slice(0, m.index).replace(/[\s　]+$/, '');
    if (!before.endsWith('</imgthink>')) out.push({ start: m.index, end: m.index + m[0].length, block: m[0] });
  }
  return out;
}

function thinkCore(raw) {
  const m = String(raw || '').match(/<imgthink>([\s\S]*?)<\/imgthink>/i);
  if (!m) return (String(raw || '').match(/【([^】]{0,40})】/) || [])[1] || '';
  let t = m[1];
  const core = t.match(/(?:原文视觉核心|视觉核心|视觉要点)[^\n]*[:：]?\s*([\s\S]{10,400}?)(?:\n\s*【|\n\s*\[S|\n\s*┌|\n\s*│)/);
  if (core && core[1] && core[1].trim().length >= 10) t = core[1];
  return t.replace(/[\[\]{}()<>]/g, ' ');
}

function parseTags(v) {
  const out = [];
  String(v || '').split(/[、,，;；\s]+/).forEach(x => {
    const m = x.replace(/[<>\/]/g, '').trim().match(/^[A-Za-z0-9_:.\-]+/);
    if (m && out.indexOf(m[0]) < 0) out.push(m[0]);
  });
  return out;
}

// 连在一起的图：相邻两张之间只有空白
function findRuns(units, text) {
  const runs = [];
  if (!units.length) return runs;
  let cur = [0];
  for (let i = 1; i < units.length; i++) {
    const gap = text.slice(units[i - 1].end, units[i].start);
    if (/^\s*$/.test(gap)) cur.push(i);
    else { runs.push(cur); cur = [i]; }
  }
  runs.push(cur);
  return runs;
}

function stripUnits(text, units, idxSet) {
  let base = '', cursor = 0;
  const moved = [];
  units.forEach((u, i) => {
    if (!idxSet.has(i)) return;
    base += text.slice(cursor, u.start);
    moved.push(u);
    cursor = u.end;
  });
  base += text.slice(cursor);
  return { base, moved };
}

// 标签内容的区域（多个标签取并集，重叠自动合并）
function regions(base, tags) {
  if (!tags.length) return [{ start: 0, end: base.length, tag: '(整条消息)' }];
  const out = [];
  for (const name of tags) {
    const re = new RegExp('<' + name + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + name + '\\s*>', 'gi');
    let m;
    while ((m = re.exec(base)) !== null) {
      const gt = m[0].indexOf('>');
      const start = m.index + gt + 1;
      out.push({ start, end: start + m[1].length, tag: name });
    }
  }
  out.sort((x, y) => x.start - y.start);
  const merged = [];
  for (const r of out) {
    const last = merged[merged.length - 1];
    if (last && r.start <= last.end) last.end = Math.max(last.end, r.end);
    else merged.push({ start: r.start, end: r.end, tag: r.tag });
  }
  return merged;
}

function paragraphsIn(base, r) {
  const txt = base.slice(r.start, r.end);
  const out = [];
  let pos = 0, m;
  const bounds = [];
  const re = /\n{2,}/g;
  while ((m = re.exec(txt)) !== null) { bounds.push([pos, m.index]); pos = m.index + m[0].length; }
  bounds.push([pos, txt.length]);
  for (const [s0, e0] of bounds) {
    let s = s0, e = e0;
    while (s < e && /\s/.test(txt[s])) s++;
    while (e > s && /\s/.test(txt[e - 1])) e--;
    if (e <= s) continue;
    out.push({ start: r.start + s, end: r.start + e, text: txt.slice(s, e) });
  }
  return out;
}

// 段落里剔除图片块，避免图自己匹配自己
function cleanPara(t) {
  return String(t || '').replace(/<imgthink>[\s\S]*?<\/imgthink>\s*<image[^>]*>[\s\S]*?<\/image>|<image[^>]*>[\s\S]*?<\/image>/g, ' ');
}

function assign(paras, texts) {
  const n = paras.length, m = texts.length;
  const pg = paras.map(p => grams(cleanPara(p)));
  const pw = pg.map(g => { let t = 0; for (const w of g.values()) t += w; return Math.sqrt(Math.max(t, 0.001)); });
  const df = new Map();
  for (const g of pg) for (const k of g.keys()) df.set(k, (df.get(k) || 0) + 1);

  const sims = [];
  for (let i = 0; i < m; i++) {
    const ug = grams(texts[i]);
    let total = 0;
    for (const w of ug.values()) total += w;
    const norm = Math.sqrt(Math.max(total, 0.001));
    const row = new Array(n + 1).fill(0);
    for (let p = 1; p <= n; p++) {
      let s = 0;
      for (const [g, w] of ug) if (pg[p - 1].has(g)) s += w / (df.get(g) || 1);
      row[p] = s / (norm * pw[p - 1]);
    }
    sims.push(row);
  }

  const order = [...Array(m).keys()].sort((x, y) => {
    const bx = Math.max(...sims[x].slice(1)), by = Math.max(...sims[y].slice(1));
    return by - bx;
  });

  const used = new Array(n + 1).fill(0);
  const out = new Array(m).fill(0);
  const info = [];
  const spread = n >= m * 2;

  for (const i of order) {
    const expect = Math.min(n, Math.max(1, Math.round((i + 1) * n / m)));
    // 相似度 + 轻微位置先验：图按顺序出现在正文里，位置越接近预期越优先
    const bonus = (p) => 0.12 * (1 - Math.min(1, Math.abs(p - expect) / Math.max(1, n)));
    let pick = 0, best = -1, bestScore = -1;
    for (let p = 1; p <= n; p++) {
      if (spread && used[p]) continue;
      const sc = sims[i][p] + bonus(p);
      if (sc > bestScore) { bestScore = sc; best = sims[i][p]; pick = p; }
    }
    let how = '相似度';
    if (pick === 0 || best < CFG.minScore) {
      how = '位置兜底';
      const cands = [];
      for (let p = 1; p <= n; p++) if (!spread || !used[p]) cands.push(p);
      if (!cands.length) for (let p = 1; p <= n; p++) cands.push(p);
      cands.sort((x, y) => Math.abs(x - expect) - Math.abs(y - expect));
      pick = cands[0];
      best = sims[i][pick];
    }
    used[pick]++;
    out[i] = pick;
    info.push({ img: i + 1, para: pick, sim: +best.toFixed(3), how });
  }
  return { pos: out, info };
}

// ── 提示词 ──────────────────────────────────────────────────────
const RULES = `硬性要求：
1. 每张图正向部分（Scene + 全部 Character Prompt，不含 UC）180-200 token；
   { } [ ] ( ) :: :1.8 , 这些符号计入，UC 不计入。
2. 人数词：1人 solo ｜ 2人 {duo},{2people} ｜ 3人 {trio},2girls,1boy ｜
   4人 {group},3girls,1boy ｜ 5人 {group},4girls,1boy。
3. 角色名一律拼音（如 Su Wanqing），禁止中文汉字；每角色 (名:1.6~1.8)。
4. 3人及以上：不写 -1.5::…::（改在 UC 写 1.5::对方发色::）；只有发色用 {{}}，其余单 {}。
5. 每角色保留：性别标签、名、{{发色}}、服装、动作、表情、位置。
6. 每一步都要写实质内容，禁止"同上 / 略 / 全✓"。`;

function buildRepairPrompt(block, ctx) {
  return `你是「电影大师」提示词格式修复器。下面这条回复里有一个 <image> 缺少紧邻的 <imgthink>。
请**只输出**一对标签，不要解释、不要代码块、不要多余文字：

<imgthink>
[S1 上下文视觉要点] 提炼正文里的视觉信息（服装/姿势/身体状态/位置/体液），40-150字，禁止复制原文
[S2 分级] 依据穿着判断 Safe / R / X 并说明依据
[S3 交互防反转] 指出动作的主语
[S4 多角色处理] 人数、人数词、空间位置；单人写"单人场景，跳过"
[S5 镜头语言] 景别 / 视角 / 构图
[S6 装填指引] 从角色DNA里摘哪几类标签（只指引，不装填）
[S6.5 年龄控制] 中年角色逐项检查；无则写"非中年，免检"
[S7 最终审计] 逐项写：人数词 / 服装颜色 / 肤色 / 权重保留 / 分级 是否通过
</imgthink>
<image>【沿用原标题】
image###Scene Composition:…;Character 1 Prompt:…;Character 1 UC:…;…###
</image>

${RULES}

【最近正文】
${ctx}

【违规的 image 原文】
${block}`;
}

function buildFillPrompt(paras, have, need) {
  return `你是「电影大师」的配图提示词生成器。这条回复目前只有 ${have} 张图，还差 ${need} 张。
请为下面每一段正文各出一对标签，共 ${need} 对，顺序与正文一致，中间空一行，只输出标签本身：

<imgthink>
[S1 上下文视觉要点] 提炼该段正文的视觉信息（服装/姿势/身体状态/位置），40-150字，禁止复制原文
[S2 分级] 依据穿着判断 Safe / R / X 并说明依据
[S3 交互防反转] 指出动作的主语
[S4 多角色处理] 人数、人数词、空间位置；单人写"单人场景，跳过"
[S5 镜头语言] 景别 / 视角 / 构图
[S6 装填指引] 从角色DNA里摘哪几类标签（只指引，不装填）
[S6.5 年龄控制] 中年角色逐项检查；无则写"非中年，免检"
[S7 最终审计] 逐项写：人数词 / 服装颜色 / 肤色 / 权重保留 / 分级 是否通过
</imgthink>
<image>【该段标题】
image###Scene Composition:…;Character 1 Prompt:…;Character 1 UC:…;…###
</image>

${RULES}

${paras.map((p, i) => '【正文 ' + (i + 1) + '】\n' + p).join('\n\n')}`;
}

async function aiFix(prompt) {
  if (typeof genRaw === 'function') {
    try { const r = await genRaw({ user_input: prompt, should_silence: true }); if (r) return r; }
    catch (e) { log('generateRaw 失败', e); }
  }
  if (typeof gen === 'function') {
    try { const r = await gen({ user_input: prompt, should_silence: true }); if (r) return r; }
    catch (e) { log('generate 失败', e); }
  }
  return '';
}

function skeleton(block) {
  const inner = block.replace(/^<image[^>]*>/, '').replace(/<\/image>$/, '').replace(/image###|###/g, ' ').trim();
  return '<imgthink>\n'
    + '[S1] 视觉要点：' + inner.slice(0, 100) + '…\n'
    + '[S2] 分级见 UC ｜ [S3] 动作已绑主语 ｜ [S4] 人数词见 Scene\n'
    + '[S5] 景别见 Scene ｜ [S6] 取自角色DNA ｜ [S6.5] 非中年 ｜ [S7] 待人工确认\n'
    + '</imgthink>\n' + block;
}

function pickPair(text) {
  const t = String(text || '');
  const th = t.match(/<imgthink>[\s\S]*?<\/imgthink>/i);
  const im = t.match(/<image[^>]*>[\s\S]*?<\/image>/i);
  return th && im ? th[0].trim() + '\n' + im[0].trim() : null;
}

function pickPairs(text) {
  const t = String(text || '');
  const out = [];
  const re = /<imgthink>[\s\S]*?<\/imgthink>\s*<image[^>]*>[\s\S]*?<\/image>/g;
  let m;
  while ((m = re.exec(t)) !== null) out.push(m[0].trim());
  if (out.length) return out;
  const re2 = /<image[^>]*>[\s\S]*?<\/image>/g;
  while ((m = re2.exec(t)) !== null) out.push(skeleton(m[0]));
  return out;
}

// 只挑标签内、还没配图的正文段落
function pickParagraphs(text, need) {
  const tags = parseTags(bodyTag);
  if (!tags.length) { log('正文标签框是空的，不补图'); return []; }
  const regs = regions(text, tags);
  if (!regs.length) { log('没找到 <' + tags.join('> / <') + '> 的范围，不补图'); return []; }

  let paras = [];
  for (const r of regs) paras = paras.concat(paragraphsIn(text, r));
  if (!paras.length) return [];

  // 图片独占的段落并到上一段，免得被当成正文
  const merged = [];
  for (const p of paras) {
    const onlyImg = /^\s*(<imgthink>[\s\S]*?<\/imgthink>\s*)?<image[^>]*>[\s\S]*?<\/image>\s*$/.test(p.text);
    if (onlyImg && merged.length) {
      const last = merged[merged.length - 1];
      last.text += '\n\n' + p.text;
      last.end = p.end;
    } else merged.push(p);
  }

  // 已有图片占用了哪些段落
  const occupied = new Set();
  const imgs = scan(text);
  if (imgs.length) {
    merged.forEach((p, i) => {
      if (/<image[^>]*>/.test(p.text)) occupied.add(i);
      const nx = merged[i + 1];
      if (nx && /^\s*(<imgthink>|<image)/.test(nx.text)) occupied.add(i);
    });
    imgs.forEach((u, k) => {
      const core = grams(thinkCore(u.raw));
      let best = -1, bestSim = 0;
      merged.forEach((p, i) => {
        const sim = cosine(core, grams(cleanPara(p.text)));
        if (sim > bestSim) { bestSim = sim; best = i; }
      });
      // 最像的那段如果已经有图了，说明这张图就属于那里，别再占用别的段
      if (best >= 0 && bestSim >= 0.12) { if (!occupied.has(best)) occupied.add(best); return; }
      const guess = Math.min(merged.length - 1, Math.max(0, Math.round((k + 1) * merged.length / imgs.length) - 1));
      if (!occupied.has(guess)) occupied.add(guess);
    });
  }

  const cands = [];
  for (let i = 0; i < merged.length; i++) {
    if (occupied.has(i)) continue;
    const p = merged[i];
    if (cleanPara(p.text).replace(/\s/g, '').length < CFG.minParaChars) continue;
    if (/^\s*(<\/?(content|memory|CURRENT_VARIABLES)>|<UpdateVariable)/i.test(p.text)) continue;
    cands.push(p);
  }
  if (!cands.length) return [];
  return cands.slice().sort((a, b) => b.text.length - a.text.length)
    .slice(0, need).sort((a, b) => a.start - b.start);
}

// ── 动作 1：图片归位 ─────────────────────────────────────────────
async function relocate(messageId) {
  const t0 = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  const list = await getMsgs(messageId);
  const msg = (list || [])[0];
  if (!msg) return { ok: false, reason: '取不到第 ' + messageId + ' 楼' };
  if (msg.role !== 'assistant') return { ok: false, reason: '最新一楼不是 AI 回复' };

  const text = msg.message || '';
  const units = scan(text);
  if (!units.length) return { ok: false, reason: '这条没有图片' };

  const tags = parseTags(bodyTag);
  const regsOrig = tags.length ? regions(text, tags) : [];
  const outsideOf = (u) => {
    if (!tags.length || !regsOrig.length) return false;
    return !regsOrig.some(r => u.start >= r.start && u.end <= r.end);
  };

  const runs = findRuns(units, text);
  const idxSet = new Set();
  runs.forEach(r => { if (r.length >= 2) r.forEach(i => idxSet.add(i)); });
  units.forEach((u, i) => { if (outsideOf(u)) idxSet.add(i); });
  if (!idxSet.size) return { ok: false, reason: '图片位置正常，无需归位' };

  const { base, moved } = stripUnits(text, units, idxSet);
  let regs = tags.length ? regions(base, tags) : [];
  let tagNote = tags.length ? tags.join('+') : '整条消息';
  if (!regs.length) {
    regs = [{ start: 0, end: base.length, tag: '(未命中，整条)' }];
    tagNote = '标签未命中，按整条消息';
    log('没找到正文标签 ' + tags.join('、') + '，改按整条消息匹配');
  }

  let paras = [];
  for (const r of regs) paras = paras.concat(paragraphsIn(base, r));
  if (!paras.length) return { ok: false, reason: '标签内没有正文段落' };

  const merged = [];
  for (const p of paras) {
    const onlyImg = /^\s*(<imgthink>[\s\S]*?<\/imgthink>\s*)?<image[^>]*>[\s\S]*?<\/image>\s*$/.test(p.text);
    if (onlyImg && merged.length) {
      const last = merged[merged.length - 1];
      last.text += '\n\n' + p.text;
      last.end = p.end;
    } else merged.push(p);
  }
  if (!merged.length) return { ok: false, reason: '标签内没有正文段落' };

  const asg = assign(merged.map(p => p.text), moved.map(u => thinkCore(u.raw)));
  const pos = asg.pos;
  asg.info.forEach(it => log('图' + it.img + ' → 第' + it.para + '段（相似度 ' + it.sim + '，' + it.how + '）'));

  const groups = {};
  pos.forEach((p, i) => { (groups[p] = groups[p] || []).push(moved[i].raw.trim()); });

  const edits = Object.keys(groups).map(k => {
    const pi = Number(k) - 1;
    return { at: merged[pi].end, text: '\n\n' + groups[k].join('\n\n') };
  }).sort((a, b) => b.at - a.at);

  let out = base;
  for (const e of edits) out = out.slice(0, e.at) + e.text + out.slice(e.at);

  if (out.trim() === text.trim()) return { ok: false, reason: '整理后无变化' };
  if (CFG.dryRun) { log('dryRun：\n' + out.slice(0, 800)); return { ok: false, reason: 'dryRun 已打印' }; }

  await setMsgs([{ message_id: messageId, message: out }]);
  const ms = ((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - t0;
  log('已归位', messageId, '移动', moved.length, '张 → 段落', pos.join(','), '| 标签:', tagNote, '| 段落数:', merged.length, '| 耗时', ms.toFixed(2) + 'ms');
  return {
    ok: true,
    reason: '移动 ' + moved.length + ' 张：' + pos.map((a, i) => '图' + (i + 1) + '→第' + a + '段').join(' ') + '（' + tagNote + ' 内共 ' + merged.length + ' 段）'
  };
}

// ── 动作 2：补 imgthink ─────────────────────────────────────────
async function repairThink(messageId) {
  const got = await getMsgs(messageId);
  const msg = (got || [])[0];
  if (!msg || msg.role !== 'assistant') return { n: 0, added: 0, why: '最新一楼不是 AI 回复' };
  const text = msg.message || '';

  const orphans = findOrphans(text).slice(0, CFG.maxRepair);
  log('修复 imgthink：缺', orphans.length, '处');
  if (!orphans.length) return { n: 0, added: 0, why: 'imgthink 都齐了' };

  const jobs = [];
  for (const o of orphans) {
    const ctx = text.slice(Math.max(0, o.start - CFG.historyChars), o.start);
    let pair = null;
    if (typeof genRaw === 'function' || typeof gen === 'function') pair = pickPair(await aiFix(buildRepairPrompt(o.block, ctx)));
    if (!pair) { log('AI 未返回可用结果，用骨架兜底'); pair = skeleton(o.block); }
    jobs.push({ block: o.block, pair });
  }

  let latest = text;
  try { const g2 = await getMsgs(messageId); if (g2 && g2[0] && typeof g2[0].message === 'string') latest = g2[0].message; } catch (e) {}
  if (latest !== text) log('文本已被其他脚本改动，按新文本重新定位', messageId);

  let out = latest, repaired = 0;
  for (let i = jobs.length - 1; i >= 0; i--) {
    const j = jobs[i];
    const idx = out.indexOf(j.block);
    if (idx < 0) { log('定位失败，跳过一处'); continue; }
    let from = idx;
    const head = out.slice(0, idx);
    const open = head.lastIndexOf('<imgthink>');
    const close = head.lastIndexOf('</imgthink>');
    if (open > close) from = open;
    out = out.slice(0, from) + j.pair + out.slice(idx + j.block.length);
    repaired++;
  }

  if (CFG.dryRun) { log('dryRun：\n' + out.slice(0, 1200)); return { n: repaired, added: 0, why: 'dryRun（think ' + repaired + '）' }; }
  if (out === latest) return { n: 0, added: 0, why: '没有可写回的内容' };
  await setMsgs([{ message_id: messageId, message: out }]);
  log('已写回', messageId, '补 imgthink', repaired, '处');
  return { n: repaired, added: 0, why: '补 imgthink ' + repaired + ' 处' };
}

// ── 动作 3：补图片 ──────────────────────────────────────────────
async function repairImages(messageId) {
  const got = await getMsgs(messageId);
  const msg = (got || [])[0];
  if (!msg || msg.role !== 'assistant') return { n: 0, added: 0, why: '最新一楼不是 AI 回复' };
  const text = msg.message || '';

  const have = countImages(text);
  const need = Math.min(CFG.maxAdd, Math.max(0, CFG.minImages - have));
  log('修复图片：现有', have, '张，缺', need, '张');
  if (need <= 0) return { n: 0, added: 0, why: '图片已够 ' + have + ' 张' };

  const tags = parseTags(bodyTag);
  if (!tags.length) return { n: 0, added: 0, why: '正文标签框为空：先填 content 等标签' };
  const cands = pickParagraphs(text, need);
  if (!cands.length) return { n: 0, added: 0, why: '标签 <' + tags.join('> <') + '> 里没有可配图的段落' };
  log('挑中', cands.length, '段正文');

  const raw = await aiFix(buildFillPrompt(cands.map(c => cleanPara(c.text).trim()), have, need));
  const pairs = pickPairs(raw).slice(0, cands.length);
  if (!pairs.length) return { n: 0, added: 0, why: 'AI 没有返回可用的图片块' };

  let latest = text;
  try { const g2 = await getMsgs(messageId); if (g2 && g2[0] && typeof g2[0].message === 'string') latest = g2[0].message; } catch (e) {}

  const ins = [];
  let from = 0;
  for (let i = 0; i < pairs.length; i++) {
    const p = cands[i];
    if (!p) break;
    const anchor = cleanPara(p.text).trim();
    let at = anchor ? latest.indexOf(anchor, from) : -1;
    if (at < 0 && anchor) at = latest.indexOf(anchor);
    if (at < 0) { log('段落定位失败，跳过一处'); continue; }
    ins.push({ at: at + anchor.length, block: pairs[i] });
    from = at + anchor.length;
  }
  if (!ins.length) return { n: 0, added: 0, why: '段落定位失败' };

  ins.sort((x, y) => y.at - x.at);
  let out = latest;
  for (const it of ins) out = out.slice(0, it.at) + '\n\n' + it.block + out.slice(it.at);

  if (CFG.dryRun) { log('dryRun：\n' + out.slice(0, 1200)); return { n: 0, added: ins.length, why: 'dryRun（图 ' + ins.length + '）' }; }
  await setMsgs([{ message_id: messageId, message: out }]);
  log('已写回', messageId, '补图', ins.length, '张');
  return { n: 0, added: ins.length, why: '补图 ' + ins.length + ' 张' };
}

async function repairAll(messageId) {
  const a = await relocate(messageId);
  const b = await repairThink(messageId);
  const c = await repairImages(messageId);
  return { ok: true, reason: [a && a.reason, b && b.why, c && c.why].filter(Boolean).join('；') };
}

// ── 界面：按钮 + 正文标签框 ──────────────────────────────────────
let needFix = false;
let boxEl = null;
let btnEl = null;
let mountTries = 0;

function saveTag(v) {
  bodyTag = String(v || '');
  try { localStorage.setItem(STORE_KEY, bodyTag); } catch (e) {}
  log('正文标签 →', bodyTag || '（空）');
}

function readBox() {
  try { if (boxEl && typeof boxEl.value === 'string') saveTag(boxEl.value); } catch (e) {}
}

function ensureBox(doc, btn) {
  try {
    if (!doc || !doc.getElementById || !doc.createElement) return false;
    const old = doc.getElementById('fm-body-tag');
    if (old) { boxEl = old; return true; }
    if (!btn || !btn.parentNode) return false;
    const inp = doc.createElement('input');
    inp.id = 'fm-body-tag';
    inp.type = 'text';
    inp.placeholder = '正文标签，如 content';
    inp.value = bodyTag;
    inp.style.cssText = 'width:150px;height:26px;padding:0 8px;margin-left:6px;border-radius:4px;box-sizing:border-box;'
      + 'background:#3c3c3c;color:#fff;border:1px solid #666;font-size:13px;outline:none;vertical-align:middle;';
    try { inp.style.webkitTextFillColor = '#fff'; inp.style.caretColor = '#fff'; } catch (e) {}
    styleLike(inp, btn);
    inp.style.width = '150px';
    inp.style.border = '1px solid #666';
    inp.style.color = '#fff';
    inp.style.marginLeft = '6px';
    inp.addEventListener('input', () => saveTag(inp.value));
    inp.addEventListener('change', () => saveTag(inp.value));
    const next = btn.nextSibling;
    if (next) btn.parentNode.insertBefore(inp, next); else btn.parentNode.appendChild(inp);
    boxEl = inp;
    log('正文标签框已就位');
    return true;
  } catch (e) { log('挂载输入框失败', e); return false; }
}

function paintUI() {
  const doc = docRef();
  if (!doc) return;
  const btn = findButton(doc);
  if (!btn) {
    if (mountTries === 1) log('暂未找到脚本按钮，继续等待渲染…');
    return;
  }
  btnEl = btn;
  const want = needFix ? '需修复' : '修复本条';
  if ((btn.textContent || '').trim() !== want) btn.textContent = want;
  ensureBox(doc, btn);
}

if (docRef()) {
  paintUI();
  const timer = setInterval(() => {
    mountTries++;
    try { paintUI(); } catch (e) {}
    if (mountTries > 2400) clearInterval(timer);
  }, 1200);
}

// ── 本地检测（不调模型）─────────────────────────────────────────
async function lastMessageId() {
  try { if (typeof TH.getLastMessageId === 'function') { const id = await TH.getLastMessageId(); if (id !== null && id !== undefined) return id; } } catch (e) {}
  try { if (typeof getMsgs === 'function') { const l = await getMsgs(-1); if (l && l.length) return l[l.length - 1].message_id; } } catch (e) {}
  return null;
}

async function detect(id) {
  try {
    const got = await getMsgs(id);
    const msg = (got || [])[0];
    if (!msg || msg.role !== 'assistant') return false;
    const text = msg.message || '';
    const units = scan(text);
    const imgs = countImages(text);
    const orphans = findOrphans(text).length;
    const runs = findRuns(units, text).filter(r => r.length >= 2).length;
    const tags = parseTags(bodyTag);
    const regs = (tags.length && units.length) ? regions(text, tags) : [];
    const outside = regs.length ? units.filter(u => !regs.some(r => u.start >= r.start && u.end <= r.end)).length : 0;
    const short = imgs < CFG.minImages;

    const before = needFix;
    needFix = short || orphans > 0 || runs > 0 || outside > 0;
    if (before !== needFix) {
      log('检测：图 ' + imgs + (short ? '(少于' + CFG.minImages + ')' : '') + '，缺think ' + orphans +
        '，连图块 ' + runs + '，标签外 ' + outside + ' → ' + (needFix ? '需修复' : '正常'));
    }
    paintUI();
    return needFix;
  } catch (e) { log('检测失败', e); return false; }
}

// ── 一键：检测完直接全部修复 ────────────────────────────────────
async function runAll() {
  const id = await lastMessageId();
  if (id === null || id === undefined) {
    toast && toast.error && toast.error('图文修复：找不到最新楼层');
    return;
  }
  readBox();
  log('开始修复第', id, '楼 | 正文标签:', bodyTag || '（空）');

  const a = await relocate(id);
  const b = await repairThink(id);
  const c = await repairImages(id);
  const done = [];
  if (a && a.ok) done.push('归位：' + a.reason);
  else if (a && a.reason) log('归位跳过：', a.reason);
  if (b && b.n > 0) done.push('补 think ' + b.n + ' 处');
  else if (b && b.why) log('think 跳过：', b.why);
  if (c && c.added > 0) done.push('补图 ' + c.added + ' 张');
  else if (c && c.why) log('补图跳过：', c.why);

  await detect(id);
  const msg = done.length ? done.join('；') : '没有需要修复的内容';
  log('修复完成：', msg, '| 按钮 →', needFix ? '需修复' : '修复本条');
  if (done.length) { toast && toast.success && toast.success(msg); }
  else { const f = (toast && (toast.info || toast.warning || toast.success)) || null; f && f(msg); }
  return { done };
}

// ── 事件 ────────────────────────────────────────────────────────
if (typeof onEvent === 'function') {
  onEvent(EVENTS.MESSAGE_RECEIVED || 'message_received', (id) => { detect(id); });
  ['MESSAGE_EDITED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED'].forEach(k => {
    const name = EVENTS[k];
    if (!name) return;
    try { onEvent(name, (id) => { if (id !== null && id !== undefined) detect(id); }); } catch (e) {}
  });
  try {
    onEvent(EVENTS.CHAT_CHANGED || 'chat_changed', () => {
      needFix = false; paintUI();
      lastMessageId().then(id => { if (id !== null && id !== undefined) detect(id); });
    });
  } catch (e) {}

  const getButtonEvent = TH.getButtonEvent || globalThis.getButtonEvent;
  if (typeof getButtonEvent === 'function') {
    const ev = getButtonEvent('修复本条') || getButtonEvent('图文修复');
    if (!ev) log('⚠️ 没拿到按钮事件');
    ev && onEvent(ev, () => {
      log('按钮点击');
      runAll().catch(e => { log('修复异常', e); toast && toast.error && toast.error('图文修复异常：' + e); });
    });
  }
}

globalThis.FM_fix = {
  runAll, relocate, repairThink, repairImages, detect, paintUI,
  scan, findRuns, regions, paragraphsIn, parseTags, assign, pickParagraphs,
  countImages, findOrphans, thinkCore,
  get bodyTag() { return bodyTag; }, set bodyTag(v) { saveTag(v); },
  get needFix() { return needFix; }
};
log('电影大师 图文修复 v3.1 加载完成', CFG);
